import{_ as a,o as i,c as t,a0 as n}from"./chunks/framework.Bogozrur.js";const g=JSON.parse('{"title":"The Jengo Installer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installer.md","filePath":"guide/installer.md"}'),s={name:"guide/installer.md"};function l(o,e,r,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-jengo-installer" tabindex="-1">The Jengo Installer <a class="header-anchor" href="#the-jengo-installer" aria-label="Permalink to &quot;The Jengo Installer&quot;">​</a></h1><p>The Jengo Installer (<code>jengo new</code>) is a powerful, interactive CLI tool designed to scaffold your entire application in seconds.</p><h2 id="interactive-mode" tabindex="-1">Interactive Mode <a class="header-anchor" href="#interactive-mode" aria-label="Permalink to &quot;Interactive Mode&quot;">​</a></h2><p>By default, running <code>jengo new &lt;app-name&gt;</code> triggers an interactive wizard. The wizard will ask you to select:</p><ol><li><strong>Starter Kit</strong>: Choose between the Default PHP kit or modern SPAs (React, Vue, Svelte).</li><li><strong>Package Manager</strong>: Select <code>npm</code>, <code>pnpm</code>, or <code>yarn</code>.</li><li><strong>TypeScript</strong>: Decide if you want full TypeScript support (strongly recommended for SPAs).</li><li><strong>The Gatekeeper</strong>: Opt-in to install our CodeIgniter Shield auth integration.</li><li><strong>The Vault</strong>: Opt-in to establish our API foundation.</li><li><strong>Tailwind CSS</strong>: Decide if you want Tailwind installed and configured.</li></ol><h2 id="non-interactive-mode-ci-cd" tabindex="-1">Non-Interactive Mode (CI/CD) <a class="header-anchor" href="#non-interactive-mode-ci-cd" aria-label="Permalink to &quot;Non-Interactive Mode (CI/CD)&quot;">​</a></h2><p>For automated setups or if you already know exactly what you want, you can pass your preferences directly via command-line flags. The installer will skip the prompts for any options provided.</p><h3 id="example-react-spa-with-auth" tabindex="-1">Example: React SPA with Auth <a class="header-anchor" href="#example-react-spa-with-auth" aria-label="Permalink to &quot;Example: React SPA with Auth&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jengo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kit=react</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pm=pnpm</span></span></code></pre></div><h3 id="available-flags" tabindex="-1">Available Flags <a class="header-anchor" href="#available-flags" aria-label="Permalink to &quot;Available Flags&quot;">​</a></h3><ul><li><code>--kit=&lt;name&gt;</code>: <code>default</code>, <code>react</code>, <code>vue</code>, or <code>svelte</code>.</li><li><code>--auth</code>: Installs the CodeIgniter Shield integration.</li><li><code>--api</code>: Installs the Jengo API suite.</li><li><code>--ts</code>: Installs TypeScript support and configurations.</li><li><code>--no-tailwind</code>: Skips Tailwind CSS installation.</li><li><code>--pm=&lt;manager&gt;</code>: <code>npm</code>, <code>pnpm</code>, or <code>yarn</code>.</li><li><code>--force</code> (<code>-f</code>): Overwrites the target directory if it already exists.</li></ul><h2 id="current-directory-installation" tabindex="-1">Current Directory Installation <a class="header-anchor" href="#current-directory-installation" aria-label="Permalink to &quot;Current Directory Installation&quot;">​</a></h2><p>If you&#39;ve already created an empty directory and want to scaffold Jengo inside it, you can pass <code>.</code> as the application name:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jengo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The installer will automatically name your application based on the current folder&#39;s name.</p>`,15)])])}const u=a(s,[["render",l]]);export{g as __pageData,u as default};
